from qdsl import Bank
TOP = {'dig': ('Đại lượng số, bit và mức logic', 'Digital quantities, bits and logic levels'), 'wave': ('Dạng sóng số: chu kỳ, tần số, độ rộng xung', 'Digital waveforms: period, frequency, pulse width'), 'gate': ('Cổng logic cơ bản và thiết bị số', 'Basic gates and digital devices'), 'ic': ('IC số và logic khả trình', 'Digital ICs and programmable logic')}
B = Bank(TOP); TFO = [('Đúng', 'True'), ('Sai', 'False')]
def tf(n, tid, vi, en, key, xv, xe):
    B.goc.append(B._item('tf', tid, 1, 'goc', vi, en, TFO, 0 if key == 'T' else 1, xv, xe, f'Floyd Ch.1 · Đúng/Sai {n} (khoá tr.64)', f'Floyd Ch.1 · True/False {n} (key p.64)'))
def st(n, tid, lv, vi, en, ops, c, xv, xe, printed=None, mk=None):
    letter = 'abcde'
    sv = f'Floyd Ch.1 · Self-Test {n} (khoá tr.64)' if not printed else f'Floyd Ch.1 · Self-Test {n} (khoá in ({printed}), đúng ({letter[c]}); tr.64)'
    se = f'Floyd Ch.1 · Self-Test {n} (key p.64)' if not printed else f'Floyd Ch.1 · Self-Test {n} (printed key ({printed}), correct ({letter[c]}); p.64)'
    B.goc.append(B._item('mcq', tid, lv, 'goc', vi, en, ops, c, xv, xe, sv, se))
tf(1, 'dig', 'Đại lượng tương tự (analog) là đại lượng có giá trị liên tục.', 'An analog quantity is one having continuous values.', 'T', 'Đại lượng analog biến thiên liên tục theo thời gian.', 'An analog quantity varies continuously.')
tf(2, 'dig', 'Một đại lượng số (digital) không có giá trị rời rạc.', 'A digital quantity has no discrete values.', 'F', 'Đại lượng số có các giá trị rời rạc.', 'A digital quantity has discrete values.')
