tf(5, 'dig', 'Trong logic dương, mức THẤP biểu diễn nhị phân 1.', 'In positive logic, a LOW level represents a binary 1.', 'F', 'Logic dương: CAO là 1, THẤP là 0.', 'Positive logic: HIGH is 1, LOW is 0.')
tf(6, 'wave', 'Sóng tuần hoàn lặp lại sau một khoảng thời gian cố định.', 'A periodic wave repeats itself at a fixed interval.', 'T', 'Khoảng đó là chu kỳ.', 'That interval is the period.')
tf(7, 'wave', 'Giản đồ thời gian cho thấy quan hệ thời gian giữa hai hay nhiều dạng sóng số.', 'A timing diagram shows the timing relationship of two or more digital waveforms.', 'T', 'Đó là định nghĩa giản đồ thời gian.', 'That is the definition of a timing diagram.')
tf(8, 'gate', 'Chức năng AND được thực hiện bằng mạch logic gọi là cổng đảo (inverter).', 'An AND function is implemented by a logic circuit known as an inverter.', 'F', 'Cổng đảo thực hiện NOT; AND do cổng AND thực hiện.', 'An inverter performs NOT; AND is done by an AND gate.')
tf(9, 'gate', 'Flip-flop là mạch logic lưỡng bền chỉ có thể lưu hai bit cùng lúc.', 'A flip-flop is a bistable logic circuit that can store only two bits at a time.', 'F', 'Một flip-flop lưu một bit.', 'A flip-flop stores one bit.')
tf(10, 'ic', 'Hai loại IC số rộng là chức năng cố định (fixed-function) và khả trình (programmable).', 'Two broad types of digital integrated circuits are fixed-function and programmable.', 'T', 'Floyd 1-5, 1-6.', 'Floyd 1-5, 1-6.')
O = lambda *a: list(a)
st(1, 'dig', 1, 'Đại lượng có các giá trị số rời rạc là:', 'A quantity having discrete numerical values is', [('đại lượng tương tự', 'an analog quantity'), ('đại lượng số', 'a digital quantity'), ('đại lượng nhị phân', 'a binary quantity'), ('đại lượng tự nhiên', 'a natural quantity')], 1, 'Rời rạc nghĩa là số.', 'Discrete means digital.')
st(2, 'dig', 1, 'Thuật ngữ bit nghĩa là:', 'The term bit means', [('một lượng dữ liệu nhỏ', 'a small amount of data'), ('một số 1 hoặc 0', 'a 1 or a 0'), ('chữ số nhị phân', 'binary digit'), ('cả (b) và (c)', 'both answers (b) and (c)')], 3, 'Bit là chữ số nhị phân, tức một giá trị 1 hoặc 0: cả (b) và (c) đều đúng.', 'A bit is a binary digit, i.e. a 1 or a 0: both (b) and (c) are true.', printed='c')
st(3, 'wave', 1, 'Khoảng thời gian giữa các điểm 50 % trên sườn lên và sườn xuống của một xung là:', 'The time interval between the 50% points on the rising and falling edges is', [('thời gian lên', 'rise time'), ('thời gian xuống', 'fall time'), ('độ rộng xung', 'pulse width'), ('chu kỳ', 'period')], 2, 'Đó là định nghĩa độ rộng xung.', 'That is the definition of pulse width.', printed='a')
st(4, 'wave', 2, 'Một xung trong một dạng sóng có tần số 50 Hz. Nó lặp lại mỗi:', 'A pulse in a certain waveform has a frequency of 50 Hz. It repeats itself every', ['1 ms', '20 ms', '50 ms', '100 ms'], 1, '$T=1/f=1/50=20$ ms.', '$T=1/f=1/50=20$ ms.')
