st(6, 'gate', 1, 'Một cổng đảo (inverter):', 'An inverter', [('thực hiện phép NOT', 'performs the NOT operation'), ('đổi CAO thành THẤP', 'changes a HIGH to a LOW'), ('đổi THẤP thành CAO', 'changes a LOW to a HIGH'), ('làm cả ba việc trên', 'does all of the above')], 3, 'Cả ba phát biểu đều đúng.', 'All three statements are true.')
st(7, 'gate', 1, 'Ngõ ra của cổng OR ở mức THẤP khi:', 'The output of an OR gate is LOW when', [('có ngõ vào nào đó ở mức CAO', 'any input is HIGH'), ('mọi ngõ vào ở mức CAO', 'all inputs are HIGH'), ('không ngõ vào nào ở mức CAO', 'no inputs are HIGH'), ('cả (a) và (b)', 'both (a) and (b)')], 2, 'OR cho CAO khi có ít nhất một ngõ vào CAO; vì thế chỉ THẤP khi không ngõ vào nào CAO.', 'An OR output is HIGH when at least one input is HIGH; so it is LOW only when no input is HIGH.', printed='b')
st(8, 'gate', 2, 'Ngõ ra của cổng AND ở mức THẤP khi:', 'The output of an AND gate is LOW when', [('có ngõ vào nào đó ở mức THẤP', 'any input is LOW'), ('mọi ngõ vào ở mức CAO', 'all inputs are HIGH'), ('không ngõ vào nào ở mức CAO', 'no inputs are HIGH'), ('cả (a) và (c)', 'both (a) and (c)')], 3, 'AND THẤP khi có ngõ vào THẤP, kể cả khi không ngõ vào nào CAO: (a) và (c) đều đúng. Khoá in là (a), chỉ nêu một phần.', 'An AND output is LOW when any input is LOW, including when no input is HIGH: (a) and (c) are both true. The printed key (a) names only part of it.', printed='a')
st(9, 'gate', 1, 'Thiết bị dùng để đổi một số nhị phân sang dạng hiển thị 7 đoạn là:', 'The device used to convert a binary number to a 7-segment display format is the', [('bộ dồn kênh', 'multiplexer'), ('bộ mã hoá', 'encoder'), ('bộ giải mã', 'decoder'), ('thanh ghi', 'register')], 2, 'Bộ giải mã BCD sang 7 đoạn.', 'A BCD-to-7-segment decoder.', printed='d')
st(10, 'gate', 1, 'Một ví dụ về thiết bị lưu trữ dữ liệu là:', 'An example of a data storage device is', [('cổng logic', 'the logic gate'), ('flip-flop', 'the flip-flop'), ('bộ so sánh', 'the comparator'), ('thanh ghi', 'the register'), ('cả (b) và (d)', 'both answers (b) and (d)')], 4, 'Flip-flop và thanh ghi đều lưu dữ liệu.', 'Flip-flops and registers both store data.')
st(11, 'ic', 1, 'VHDL là:', 'VHDL is a', [('một thiết bị logic', 'logic device'), ('một ngôn ngữ lập trình PLD', 'PLD programming language'), ('một ngôn ngữ máy tính', 'computer language'), ('logic mật độ rất cao', 'very high density logic')], 1, 'VHDL (VHSIC HDL) là ngôn ngữ mô tả phần cứng để lập trình thiết bị logic khả trình (Module 14).', 'VHDL (VHSIC HDL) is a hardware description language used to program programmable logic devices (Module 14).', printed='c')
