st(13, 'ic', 1, 'FPGA là viết tắt của:', 'An FPGA is a', [('field-programmable gate array', 'field-programmable gate array'), ('fast programmable gate array', 'fast programmable gate array'), ('field-programmable generic array', 'field-programmable generic array'), ('flash process gate application', 'flash process gate application')], 0, 'Field-Programmable Gate Array (Module 11).', 'Field-Programmable Gate Array (Module 11).', printed='d')
st(14, 'ic', 1, 'Một IC chức năng cố định chứa bốn cổng AND là ví dụ của:', 'A fixed-function IC package containing four AND gates is an example of', ['MSI', 'SMT', 'SOIC', 'SSI'], 3, 'Bốn cổng là mức tích hợp nhỏ (SSI, tới 10 cổng tương đương).', 'Four gates is small-scale integration (SSI, up to 10 equivalent gates).')
st(15, 'ic', 2, 'Một thiết bị LSI có độ phức tạp mạch từ:', 'An LSI device has a circuit complexity of from', [('10 đến 100 cổng tương đương', '10 to 100 equivalent gates'), ('hơn 100 đến 10 000 cổng tương đương', 'more than 100 to 10,000 equivalent gates'), ('2 000 đến 5 000 cổng tương đương', '2000 to 5000 equivalent gates'), ('hơn 10 000 đến 100 000 cổng tương đương', 'more than 10,000 to 100,000 equivalent gates')], 1, 'SSI tới 10, MSI 10 đến 100, LSI hơn 100 đến 10 000, VLSI hơn 10 000 đến 100 000 (Floyd 1-6).', 'SSI up to 10, MSI 10 to 100, LSI over 100 to 10,000, VLSI over 10,000 to 100,000 (Floyd 1-6).')
def fq(f):
    for u, k in (('MHz', 1e6), ('kHz', 1e3), ('Hz', 1)):
        if f >= k * 0.999: return f'{f / k:g} {u}'
def tm(t):
    for u, k in (('s', 1), ('ms', 1e-3), ('μs', 1e-6), ('ns', 1e-9)):
        if t >= k * 0.999: return f'{round(t / k, 6):g} {u}'
X = B.X
for f in (200, 2000, 40000, 5e6):
    T = 1 / f; X('wave', 2, f'Một dạng sóng tuần hoàn có tần số {fq(f)}. Chu kỳ của nó là:', f'A periodic waveform has a frequency of {fq(f)}. Its period is:', [tm(T), tm(T * 10), tm(T / 10), tm(T * 2)], 0, f'$T=1/f=1/{fq(f)}$ = {tm(T)}.', f'$T=1/f=1/{fq(f)}$ = {tm(T)}.', 'Chu kỳ từ tần số', 'Period from frequency')
for T in (4e-3, 25e-9, 0.5e-3):
    f = 1 / T; X('wave', 2, f'Một dạng sóng có chu kỳ {tm(T)}. Tần số của nó là:', f'A waveform has a period of {tm(T)}. Its frequency is:', [fq(f), fq(f * 10), fq(f / 10), fq(f * 2)], 0, f'$f=1/T=1/{tm(T)}$ = {fq(f)}.', f'$f=1/T=1/{tm(T)}$ = {fq(f)}.', 'Tần số từ chu kỳ', 'Frequency from period')
for tw, T in ((2e-6, 8e-6), (3e-3, 10e-3), (5e-9, 20e-9)):
    d = tw / T * 100; X('wave', 2, f'Một xung có độ rộng {tm(tw)} và chu kỳ {tm(T)}. Chu kỳ làm việc (duty cycle) là:', f'A pulse has a width of {tm(tw)} and a period of {tm(T)}. The duty cycle is:', [f'{d:g} %', f'{d * 2:g} %', f'{d / 2:g} %', f'{100 - d:g} %'], 0, f'$t_W/T\\times100$ = {d:g} %.', f'$t_W/T\\times100$ = {d:g} %.', 'Chu kỳ làm việc', 'Duty cycle')
X('wave', 2, 'Một dạng sóng có chu kỳ 5 ms và chu kỳ làm việc 40 %. Độ rộng xung là:', 'A waveform has a period of 5 ms and a duty cycle of 40 %. The pulse width is:', ['2 ms', '1 ms', '3 ms', '4 ms'], 0, '$t_W=0{,}40\\times5$ ms = 2 ms.', '$t_W=0.40\\times5$ ms = 2 ms.', 'Độ rộng xung', 'Pulse width')
for nb in (6, 8, 10):
    X('dig', 2, f'Với {nb} bit nhị phân có thể biểu diễn bao nhiêu giá trị khác nhau?', f'How many different values can {nb} binary bits represent?', [str(2 ** nb), str(nb * nb), str(2 * nb), str(2 ** nb - 1)], 0, f'$2^{nb}={2 ** nb}$ (từ 0 đến {2 ** nb - 1}).', f'$2^{nb}={2 ** nb}$ (from 0 to {2 ** nb - 1}).', 'Số giá trị của n bit', 'Values of n bits')
X('wave', 3, 'Xung clock 1 MHz. Số xung clock xảy ra trong 2,5 ms là:', 'A 1 MHz clock. The number of clock pulses in 2.5 ms is:', ['2,500'.replace(',', ','), '250', '25,000', '2.5'], 0, '$f\\,t=10^6\\times2{,}5\\times10^{-3}$ = 2 500 xung.', '$f\\,t=10^6\\times2.5\\times10^{-3}$ = 2,500 pulses.', 'Số xung clock', 'Number of clock pulses')
